package in.recallradar;
import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/recalls") class RecallController{private final RecallService service;private final TenantService tenants;RecallController(RecallService s,TenantService t){service=s;tenants=t;}private Membership m(Authentication a,String org){return tenants.membership(UUID.fromString(a.getName()),org);}@GetMapping List<RecallResponse> list(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org){return service.list(m(a,org));}@GetMapping("/{id}/impact") RecallImpactAnalysisResponse impact(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org,@PathVariable UUID id){return service.impact(m(a,org),id);}@PostMapping @ResponseStatus(HttpStatus.CREATED) RecallResponse create(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org,@Valid @RequestBody RecallRequest r){return service.create(m(a,org),r);}@PutMapping("/{id}/status") RecallResponse status(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org,@PathVariable UUID id,@Valid @RequestBody RecallStatusRequest r){return service.status(m(a,org),id,r);}}
